import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJFGRv8Z.js";var i=JSON.parse(`{"title":"域名与邮件投递","description":"","frontmatter":{},"headers":[],"relativePath":"admin/domains-delivery.md","filePath":"admin/domains-delivery.md","lastUpdated":1788621106000}`),a={name:`admin/domains-delivery.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="域名与邮件投递" tabindex="-1">域名与邮件投递 <a class="header-anchor" href="#域名与邮件投递" aria-label="Permalink to “域名与邮件投递”">​</a></h1><h2 id="公共域名上线流程" tabindex="-1">公共域名上线流程 <a class="header-anchor" href="#公共域名上线流程" aria-label="Permalink to “公共域名上线流程”">​</a></h2><ol><li>添加域名并设置 MX Host。</li><li>决定是否对用户可见、允许注册邮箱、启用 Catch-All 和允许发信。</li><li>设置创建邮箱所需的最低系统配额等级 <code>L0</code>–<code>L4</code>。</li><li>生成 DKIM，并发布页面给出的 DNS 记录。</li><li>发布 MX、SPF 和 DMARC。</li><li>运行 DNS 健康检查。</li><li>用测试邮箱完成收信、发信、回复和附件验证。</li></ol><p>域名最低等级比较的是本站系统配额 <code>L</code> 档位。NodeLoc 用户先按后台映射换算，再参与比较；不要直接拿 NodeLoc <code>TL</code> 数字判断。</p><h2 id="dns-记录" tabindex="-1">DNS 记录 <a class="header-anchor" href="#dns-记录" aria-label="Permalink to “DNS 记录”">​</a></h2><p>页面给出的记录值是当前系统的准确信息。典型结构：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>A      mail       &lt;服务器公网 IP&gt;       DNS only</span></span>
<span class="line"><span>MX     @          mail.example.com     优先级 10</span></span>
<span class="line"><span>TXT    @          v=spf1 mx ~all</span></span>
<span class="line"><span>TXT    &lt;selector&gt;._domainkey           &lt;后台显示的 DKIM 公钥&gt;</span></span>
<span class="line"><span>TXT    _dmarc     v=DMARC1; p=none; rua=mailto:dmarc@example.com</span></span></code></pre></div><p>MX 优先级数值越小越优先，只有一个接收服务器时填 <code>10</code> 即可。MX 决定收信去向，不是认证 SMTP 发信所需的登录配置。</p><p>轮换 DKIM 时先发布新公钥并等待生效，再切换签名，最后移除旧记录。PTR/rDNS 通常由服务器提供商设置，应指向邮件主机名。</p><h2 id="域名开关" tabindex="-1">域名开关 <a class="header-anchor" href="#域名开关" aria-label="Permalink to “域名开关”">​</a></h2><ul><li>“对用户可见”决定普通邮箱创建页是否展示。</li><li>“允许用户注册邮箱”决定普通用户能否在该域名下创建地址。</li><li>“禁止该域名发信”关闭业务邮件发送，但仍可接收。</li><li>“发信不需要能量”使该域名按策略免能量扣费。</li><li>Catch-All 会接收未创建地址的邮件，应防范垃圾邮件和容量增长。</li></ul><h2 id="临时发信权限" tabindex="-1">临时发信权限 <a class="header-anchor" href="#临时发信权限" aria-label="Permalink to “临时发信权限”">​</a></h2><p>当域名禁止发信且全局开启“发信需要临时申请”时，用户可以提交用途说明，管理员在域名页批准或拒绝。批准前核对使用场景、预期量、收件人来源和退订机制。</p><p>关闭全局申请后，用户可按能量和配额规则发送；域名、通道、黑名单和反滥用检查仍然生效。</p><h2 id="直接-mx-与出站通道" tabindex="-1">直接 MX 与出站通道 <a class="header-anchor" href="#直接-mx-与出站通道" aria-label="Permalink to “直接 MX 与出站通道”">​</a></h2><p>平台可以直接向收件域名 MX 投递，也可使用后台配置的出站通道。正常路由默认只让 Microsoft 托管的收件域先尝试中继，其他外部域名直接投递到 MX；临时开启 <code>RELAY_ALL_OUTBOUND=true</code> 时所有外部收件人都会先尝试中继。中继不可用时仍会尝试直接 MX。</p><p>通道先匹配发信域名；指定域名的通道优先于全局通道，同一范围内优先级数字越大越先尝试，达到小时或每日上限时自动尝试下一条。这里的优先级方向与 MX 记录相反。</p><p>Resend、SendFlare 和自定义通道当前都走认证 SMTP 中转。通道密码/API Key 加密保存。业务发信通道与注册验证码使用的“系统 SMTP”分开配置。</p><h2 id="配额、能量与并发" tabindex="-1">配额、能量与并发 <a class="header-anchor" href="#配额、能量与并发" aria-label="Permalink to “配额、能量与并发”">​</a></h2><p>个人邮箱发送前检查用户每日收件人数配额、必要能量、通道小时/每日额度和已预留额度。企业邮箱改为检查其组织企业套餐的共享每日收件人数额度；同一组织下所有成员和邮箱共同计数，不占用受派成员的个人额度或能量。企业额度 <code>0</code> 表示不限，组织没有生效或宽限期套餐时禁止发信。</p><p>系统在外部投递前原子预留，按本地投递成功或远端 SMTP 服务器已接受的收件人数结算，并释放未成功部分，避免并发请求突破个人、组织或通道上限。个人与组织每日统计都以 UTC 日期为边界。</p><p>每日发信按收件人数计算，To、Cc、Bcc 都计入。网页写信、SMTP Submission、邮箱/规则转发和自动回复使用同一套个人或组织额度口径；自动回复同样会在发送前预留并在失败后释放。客户端超时后不要盲目重复提交，先查看已发送和邮件流转状态。</p><h2 id="投递失败与抑制" tabindex="-1">投递失败与抑制 <a class="header-anchor" href="#投递失败与抑制" aria-label="Permalink to “投递失败与抑制”">​</a></h2><p>直接 MX 投递依赖 DNS、TLS、IP 信誉和远端策略；中继还依赖服务商凭据和额度。永久失败或达到网络失败阈值的收件人可能进入抑制名单，防止持续重试。</p><p>解除抑制前先确认地址或网络已恢复。只删名单、不处理根因会再次退信并影响信誉。</p><h2 id="入站与重复邮件" tabindex="-1">入站与重复邮件 <a class="header-anchor" href="#入站与重复邮件" aria-label="Permalink to “入站与重复邮件”">​</a></h2><p>SMTP 接收会检查目标邮箱、容量、规则和 rspamd 结果。上游在连接中断后可能重试同一封邮件；系统用原始内容指纹和短时间窗口减少同一重试在同一邮箱中产生重复副本，同时允许以后再次收到字节完全相同但确属新投递的邮件。</p><h2 id="rspamd-处理结果" tabindex="-1">rspamd 处理结果 <a class="header-anchor" href="#rspamd-处理结果" aria-label="Permalink to “rspamd 处理结果”">​</a></h2><p>rspamd 分数达到垃圾箱阈值时，邮件进入垃圾邮件文件夹；达到隔离阈值且启用高风险隔离时，完整原文和认证结果会保存到邮箱所有者的安全隔离区。用户可用净化预览检查正文，再放行到收件箱或永久删除。发件人白名单会绕过垃圾邮件与隔离结果；rspamd 不可用时系统记录错误并继续收信。</p><p>隔离原文计入邮箱所属个人或组织的存储配额，并按“垃圾箱与垃圾邮件永久清理天数”自动删除。调低阈值或启用隔离前，先观察 rspamd 分数、误判率和存储增长，并确认用户知道如何检查“被拦截邮件”。发件域的 DMARC <code>p=reject</code> 失败属于独立认证策略，仍可能直接在 SMTP 阶段拒绝。</p><h2 id="tls" tabindex="-1">TLS <a class="header-anchor" href="#tls" aria-label="Permalink to “TLS”">​</a></h2><p><code>mail.to9.us</code> 的 SMTP STARTTLS、IMAPS 和 POP3S 必须提供有效且主机名匹配的证书。证书更新后验证各端口实际握手，不只检查网页 HTTPS。</p>`,32)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};